690	// markSeen records every member sequence, rejecting 0 and duplicates.
691	func markSeen(members []indexMember, seen map[uint64]bool) bool {
692		for _, m := range members {
693			if m.seq == 0 || seen[m.seq] {
694				return false
695			}
696			seen[m.seq] = true
697		}
698		return true
699	}
