779	// Append stages a batch of records and reserves the next sequence number
780	// for it. The batch becomes readable only after Commit or CommitGroup.
781	func (l *Log) Append(records [][]byte) (Batch, error) {
782		l.mu.Lock()
783		defer l.mu.Unlock()
784		if l.closed {
785			return Batch{}, errClosed
786		}
787		recs := copyRecords(records)
788		seq := l.nextSeq
789		l.nextSeq++
790		l.staged[seq] = recs
791		return Batch{seq: seq, records: recs, owner: l}, nil
792	}
793	
794	// Commit makes a staged batch durable and readable, and returns its
795	// reserved sequence number. Committing a batch that is not staged —
796	// including one already committed — returns ErrUnknownBatch. With
797	// Options.Sync a returned commit is durable: the segment entry and the
798	// index sidecar record are both synced, one fsync each. If either
799	// fsync fails Commit returns ErrSyncFailed, rolls both files back and
800	// the batch stays staged, keeping its reserved sequence for a retry
801	// that cannot produce a duplicate entry.
802	func (l *Log) Commit(b Batch) (uint64, error) {
803		l.mu.Lock()
804		defer l.mu.Unlock()
805		if l.closed {
806			return 0, errClosed
807		}
808		recs, ok := l.staged[b.seq]
809		if !ok || b.owner != l {
810			return 0, ErrUnknownBatch
811		}
812		entry := encodeBatch(b.seq, recs)
813		idxBefore := l.idxSize
814		off, err := l.writeEntry(entry)
815		if err != nil {
816			return 0, err
817		}
818		if l.opts.Sync {
819			if err := syncFile(l.file); err != nil {
820				// The batch stays staged and keeps its reserved sequence;
821				// a later Commit retries. Drop the un-synced entry so the
822				// retry cannot duplicate it on disk.
823				l.rollbackEntry(off, idxBefore)
824				return 0, fmt.Errorf("%w: %v", ErrSyncFailed, err)
825			}
826		}
827		rec := encodeEntryRecord(indexEntry{
828			seg:     l.segIndex,
829			off:     off,
830			length:  len(entry),
831			diskCRC: binary.LittleEndian.Uint32(entry[len(entry)-4:]),
832			members: []indexMember{{
833				seq: b.seq, off: off + len(segmentMagic),
834				length: len(entry) - len(segmentMagic) - 4,
835			}},
836		})
837		if err := l.appendIndexRecord(rec); err != nil {
838			// Index write/fsync failed: the commit is not published. Roll
839			// the index record and the segment entry both back so a retry
840			// republishes exactly once.
841			l.rollbackEntry(off, idxBefore)
842			return 0, err
843		}
844		delete(l.staged, b.seq)
845		l.gen++
846		l.index[b.seq] = entryRef{seg: l.segIndex, off: off + len(segmentMagic), length: len(entry) - len(segmentMagic) - 4, gen: l.gen}
847		l.commitSpan(b.seq, b.seq, 1)
848		return b.seq, nil
849	}
