963	// scanSnapshot is a read-consistent visibility boundary: a batch is
964	// visible only when its publication generation is <= gen and its
965	// sequence is <= highSeq. The boundary is captured in one brief
966	// read-lock acquisition, so a group that commits after a replay starts
967	// (even one filling an earlier reserved hole) is either wholly inside
968	// the snapshot or wholly outside it.
969	type scanSnapshot struct {
970		gen     uint64
971		highSeq uint64
972	}
973	
974	// Scan replays committed batches with sequence >= from in increasing
975	// sequence order, stopping at the first error returned by fn.
976	//
977	// The replay is a consistent snapshot: batches committed after the
978	// replay starts are invisible to it, and a group commit is seen either
979	// whole or not at all. The replay streams batches straight from the
980	// segment files one sequence at a time and keeps only the current
981	// batch in memory; it never loads the whole replay first. Each
982	// sequence lookup takes the lock briefly, while the file read, decode
983	// and the fn callback all run outside it, so a long replay never
984	// blocks writers.
985	func (l *Log) Scan(from uint64, fn func(Batch) error) error {
986		l.mu.RLock()
987		if l.closed {
988			l.mu.RUnlock()
989			return errClosed
990		}
991		snap := scanSnapshot{gen: l.gen, highSeq: l.nextSeq - 1}
992		l.mu.RUnlock()
993	
994		if from > snap.highSeq {
995			return nil
996		}
997		for seq := from; ; {
998			// One brief read-lock per sequence: only the index metadata is
999			// touched while holding it.
1000			l.mu.RLock()
1001			ref, ok := l.index[seq]
1002			l.mu.RUnlock()
1003			// Skip holes (reserved but uncommitted sequences) and batches
1004			// published after the snapshot was taken.
1005			if ok && ref.gen <= snap.gen {
1006				records, err := l.readRef(seq, ref)
1007				if err != nil {
1008					return err
1009				}
1010				if err := fn(Batch{seq: seq, records: records, owner: l}); err != nil {
1011					return err
1012				}
1013			}
1014			if seq == snap.highSeq {
1015				break
1016			}
1017			seq++
1018		}
1019		return nil
1020	}
