1082	// commitSpan records n newly committed batches covering sequences
1083	// [first, last] in the segment listing.
1084	func (l *Log) commitSpan(first, last uint64, n int) {
1085		if l.curBatches == 0 {
1086			l.segs = append(l.segs, Segment{FirstSeq: first, LastSeq: last})
1087		} else {
1088			seg := &l.segs[len(l.segs)-1]
1089			if first < seg.FirstSeq {
1090				seg.FirstSeq = first
1091			}
1092			if last > seg.LastSeq {
1093				seg.LastSeq = last
1094			}
1095		}
1096		l.curBatches += n
1097	}
