1099	// rollbackEntry undoes a commit that failed after its segment entry was
1100	// written: the segment file is truncated back to segOff and the just
1101	// appended index sidecar record back to idxSize. The batches involved
1102	// remain staged and a retry writes each entry exactly once.
1103	func (l *Log) rollbackEntry(segOff, idxSize int) {
1104		if l.file != nil {
1105			l.file.Truncate(int64(segOff))
1106			l.fileSize = segOff
1107		}
1108		l.truncateIndex(idxSize)
1109	}
