1111	// rewriteTail drops a torn tail from segment n and, when the torn entry
1112	// carried recoverable sequences, replaces it with a synced hole marker
1113	// so the reserved sequences stay permanent holes across reopens.
1114	func (l *Log) rewriteTail(n, off int, seqs []uint64) error {
1115		path := l.segmentPath(n)
1116		if err := os.Truncate(path, int64(off)); err != nil {
1117			return err
1118		}
1119		keep := make([]uint64, 0, len(seqs))
1120		for _, seq := range seqs {
1121			if seq > 0 {
1122				keep = append(keep, seq)
1123			}
1124		}
1125		if len(keep) == 0 {
1126			return nil
1127		}
1128		f, err := os.OpenFile(path, os.O_WRONLY|os.O_APPEND, 0)
1129		if err != nil {
1130			return err
1131		}
1132		if _, err := f.Write(encodeHoles(keep)); err != nil {
1133			f.Close()
1134			return err
1135		}
1136		if err := f.Sync(); err != nil {
1137			f.Close()
1138			return err
1139		}
1140		return f.Close()
1141	}
