1143	// writeEntry appends one encoded entry to the current segment, rolling
1144	// to a new segment when the current one is non-empty and would exceed
1145	// the configured capacity, and returns the offset the entry was
1146	// written at.
1147	func (l *Log) writeEntry(entry []byte) (int, error) {
1148		if l.file != nil && l.fileSize > 0 && l.fileSize+len(entry) > l.opts.SegmentBytes {
1149			if err := l.file.Close(); err != nil {
1150				return 0, err
1151			}
1152			l.file = nil
1153			l.segIndex++
1154			l.curBatches = 0
1155		}
1156		if l.file == nil {
1157			if l.segIndex == 0 {
1158				l.segIndex = 1
1159			}
1160			if err := l.openCurrent(); err != nil {
1161				return 0, err
1162			}
1163		}
1164		off := l.fileSize
1165		n, err := l.file.Write(entry)
1166		if err != nil {
1167			return 0, err
1168		}
1169		l.fileSize += n
1170		return off, nil
1171	}
