1192	// indexPath is the persistent index sidecar, one file per log directory.
1193	func (l *Log) indexPath() string {
1194		return filepath.Join(l.dir, "index.idx")
1195	}
1196	
1197	// syncDir fsyncs the log directory so a freshly renamed sidecar (or
1198	// created segment file) is durable itself. Best effort on filesystems
1199	// that cannot fsync directories.
1200	func syncDir(dir string) error {
1201		d, err := os.Open(dir)
1202		if err != nil {
1203			return err
1204		}
1205		err = d.Sync()
1206		if cerr := d.Close(); err == nil {
1207			err = cerr
1208		}
1209		return err
1210	}
1211	
1212	func copyRecords(records [][]byte) [][]byte {
1213		out := make([][]byte, len(records))
1214		for i, r := range records {
1215			cp := make([]byte, len(r))
1216			copy(cp, r)
1217			out[i] = cp
1218		}
1219		return out
1220	}
