func (l *Log) readRefKeyed(seq uint64, ref entryRef) ([][]byte, error) {
	f, err := os.Open(l.segmentPath(ref.seg))
	if err != nil {
		return nil, err
	}
	defer f.Close()
	body := make([]byte, ref.length)
	if _, err := f.ReadAt(body, int64(ref.off)); err != nil {
		return nil, err
	}
	got, records, err := decodeKeyedBody(body, ref.key)
	if err != nil {
		return nil, err
	}
	if got != seq {
		return nil, ErrCorruptSegment
	}
	return records, nil
}

