// verifyMixedMemberPrefix re-verifies the per-member key prefix that
// immediately precedes a member's plain body inside a BCLM mixed group:
// a single flag byte, then for a keyed member a 4-byte key length and
// the key bytes matching the index. It returns the offset of the flag
// byte. Members of a mixed group always use the plain body layout, so
// keyedBody must not be set there.
func verifyMixedMemberPrefix(f *os.File, r *sidecarRec, m indexMember) (int, bool) {
	if m.keyedBody {
		return 0, false
	}
	if m.key == "" {
		pstart := m.off - 1
		var flag [1]byte
		if pstart < r.off+8 {
			return 0, false
		}
		if _, err := f.ReadAt(flag[:], int64(pstart)); err != nil {
			return 0, false
		}
		return pstart, flag[0] == 0
	}
	var kl [4]byte
	if _, err := f.ReadAt(kl[:], int64(m.off-5)); err != nil {
		return 0, false
	}
	if uint32(len(m.key)) != binary.LittleEndian.Uint32(kl[:]) {
		return 0, false
	}
	pstart := m.off - 5 - len(m.key)
	var flag [1]byte
	if pstart < r.off+8 {
		return 0, false
	}
	if _, err := f.ReadAt(flag[:], int64(pstart)); err != nil {
		return 0, false
	}
	if flag[0] != memberKeyFlag {
		return 0, false
	}
	kb := make([]byte, len(m.key))
	if _, err := f.ReadAt(kb, int64(pstart+5)); err != nil {
		return 0, false
	}
	if string(kb) != m.key {
		return 0, false
	}
	return pstart, true
}

